examples.template:
MonarchDependencyPicker(
    links: links,
    items: Self.issues,
    excludedIDs: [{{excludeIds.0}}],
    onAdd: { relation, item in
        links.append(MonarchDependencyLink(id: "\(relation.rawValue)-\(item.id)", relation: relation, item: item))
    },
    onRemove: { link in links.removeAll { $0.id == link.id } }
)

